constraints:
1 ≤ S.length() ≤ 10^{5}
1 ≤ K ≤ 10^{4}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def ReFormatString(self, S, K):
		c = K
		N = len(S)
		size = 0
		ans = []
		for j in range(N - 1, -1, -1):
			tmp = S[j]
			if tmp >= 'a' and tmp <= 'z':
				tmp = chr(65 + (ord(tmp) - 97))
			if S[j] != '-' and c:
				ans.append(tmp)
				c -= 1
				size += 1
			elif c == 0:
				c = K
				ans.append('-')
				size += 1
				if S[j] != '-':
					ans.append(tmp)
					c -= 1
					size += 1
		if size == 0:
			return ''
		if ans[size - 1] == '-':
			ans.pop()
		ans = ans[::-1]
		return ''.join(ans)
